/**
 * The types `save/themes/` exports, in one place.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    ThemeItemSaveRow, ThemesSaveExtract
 * depends    src/save/catalogs/types
 * used by    src/save/themes/index, src/save/themes/read
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import type { ThemeCatalogCategory } from '../catalogs/types'

/** One unlocked theme item: its category, index and catalog name, if the catalog has it. */
export interface ThemeItemSaveRow {
  category: ThemeCatalogCategory
  index: number
  /** Null for an index the catalog has no row for, which is reported in `warnings`. */
  name: string | null
  selected: boolean
}

export interface ThemesSaveExtract {
  /** Every unlocked item, per category, by index. Names repeat across categories ("Glitch"). */
  unlocked: ThemeItemSaveRow[]
  /** The selected item's index per category, where the save records one. */
  selected: Partial<Record<ThemeCatalogCategory, number>>
  /** Theme items bought, as the game counts them. */
  skinsBought: number | null
  warnings: string[]
}
